	m.mu.RLock()
	defer m.mu.RUnlock()
	var events []Event
	seen := make(map[Event]bool)
	for _, t := range m.transitions {
		if t.From == m.current && !seen[t.Event] {
			events = append(events, t.Event)
			seen[t.Event] = true
		}
	}
