    basename = ".".join(str(path).split(".")[:-1])
    try:
        build = subprocess.run(
            ["rustc", path, "-o", basename], capture_output=True, timeout=15
        )
    except subprocess.TimeoutExpired as exc:
        return {
            "status": "Timeout",
            "exit_code": -1,
            "stdout": "Compiler timeout",
            "stderr": "Compiler timeout",
        }
