"""Verify every exported top-level Go symbol in this directory has a doc
comment whose first line starts with "// <Name>".

Scans *.go (excluding *_test.go) in the current directory. Recognizes top-level
func, method, type, const, and var declarations whose identifier begins with
an uppercase letter. Exits non-zero on the first missing or malformed comment.
"""
import re
import sys
from pathlib import Path

PATTERNS = [
    re.compile(r"^func\s+(?:\([^)]+\)\s+)?([A-Z]\w*)\s*\("),
    re.compile(r"^type\s+([A-Z]\w*)\s"),
    re.compile(r"^const\s+([A-Z]\w*)\s*="),
    re.compile(r"^var\s+([A-Z]\w*)\s"),
]


def exported_name(line: str):
    for pat in PATTERNS:
        m = pat.match(line)
        if m:
            return m.group(1)
    return None


def check_file(path: Path):
    lines = path.read_text().splitlines()
    errors = []
    for i, line in enumerate(lines):
        name = exported_name(line)
        if name is None:
