			// Call callbacks outside the loop-wait
			callbacks := m.callbacks[t.To]
			for _, cb := range callbacks {
				cb(old)
			}
			return t.To, nil
		}
	}
	return m.current, fmt.Errorf("no transition from %s on event %s", m.current, event)
