"""Reference Python implementation — port this to Go.

An LRU cache with a fixed capacity. get(k) returns (value, True) on hit and
(None, False) on miss. put(k, v) inserts or updates; if the insertion exceeds
capacity, the least-recently-used key is evicted. Both get and put count as a
"use" of the key. len() returns the current number of entries.
"""

from collections import OrderedDict


class LRUCache:
    def __init__(self, capacity):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self.capacity = capacity
        self._data = OrderedDict()

    def get(self, key):
        if key not in self._data:
            return None, False
        self._data.move_to_end(key)
        return self._data[key], True

    def put(self, key, value):
        if key in self._data:
            self._data.move_to_end(key)
            self._data[key] = value
            return
        if len(self._data) >= self.capacity:
            self._data.popitem(last=False)
        self._data[key] = value

    def __len__(self):
        return len(self._data)

    def keys_in_order(self):
        """Return keys from least-recently-used to most-recently-used."""
        return list(self._data.keys())

